const priceAround = `-- name: PriceAround :one
SELECT price_minor FROM (
  (SELECT pp.price_minor, 0 AS side FROM market.price_points pp
   WHERE pp.series_id = $1 AND pp.status = 'published' AND pp.observed_at < $2
   ORDER BY pp.observed_at DESC LIMIT 1)
  UNION ALL
  (SELECT pp.price_minor, 1 AS side FROM market.price_points pp
   WHERE pp.series_id = $1 AND pp.status = 'published' AND pp.observed_at > $2
   ORDER BY pp.observed_at ASC LIMIT 1)
) around ORDER BY side LIMIT 1
`

type PriceAroundParams struct {
	SeriesID int32
	At       pgtype.Timestamptz
}

// The published price nearest to a moment, for the outlier gate of a back-dated quote: the last one before it, or
// (when there is none) the first one after it. No row = the series has no published price at all.
func (q *Queries) PriceAround(ctx context.Context, arg PriceAroundParams) (int64, error) {
	row := q.db.QueryRow(ctx, priceAround, arg.SeriesID, arg.At)
	var price_minor int64
	err := row.Scan(&price_minor)
	return price_minor, err
}

const seriesPoints = `-- name: SeriesPoints :many
SELECT (max(observed_at))::timestamptz AS t,
       ((array_agg(price_minor ORDER BY observed_at DESC))[1])::bigint AS price_minor
FROM market.price_points
WHERE series_id = $1 AND status = 'published'
  AND observed_at >= $2 AND observed_at <= $3
GROUP BY date_bin(make_interval(secs => $4::int), observed_at, '2000-01-01 00:00:00+03:30'::timestamptz)
ORDER BY t
`

type SeriesPointsParams struct {
	SeriesID      int32
	Since         pgtype.Timestamptz
	Until         pgtype.Timestamptz
	BucketSeconds int32
}

type SeriesPointsRow struct {
	T          pgtype.Timestamptz
	PriceMinor int64
}

// Downsampled history: the last published price per bucket. Buckets are aligned to Tehran midnight so daily
// buckets are calendar days in Iran.
func (q *Queries) SeriesPoints(ctx context.Context, arg SeriesPointsParams) ([]SeriesPointsRow, error) {
	rows, err := q.db.Query(ctx, seriesPoints,
		arg.SeriesID,
		arg.Since,
		arg.Until,
		arg.BucketSeconds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SeriesPointsRow{}
	for rows.Next() {
		var i SeriesPointsRow
		if err := rows.Scan(&i.T, &i.PriceMinor); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

