const sourceHealth = `-- name: SourceHealth :many
SELECT src.slug, src.name_fa, src.name_en, src.provider, src.active, src.fetch_interval_s, src.stale_after_s,
       lr.started_at AS last_run_at, COALESCE(lr.status, '')::text AS last_run_status, lr.error AS last_error,
       (SELECT max(r.started_at) FROM market.source_runs r WHERE r.source_id = src.id AND r.status = 'ok')::timestamptz AS last_success_at,
       (SELECT max(pp.created_at) FROM market.price_points pp WHERE pp.source_id = src.id)::timestamptz AS last_point_at
FROM market.sources src
LEFT JOIN LATERAL (
  SELECT r.started_at, r.status, r.error FROM market.source_runs r
  WHERE r.source_id = src.id ORDER BY r.started_at DESC LIMIT 1
) lr ON true
ORDER BY src.slug
`

type SourceHealthRow struct {
	Slug           string
	NameFa         string
	NameEn         pgtype.Text
	Provider       string
	Active         bool
	FetchIntervalS int32
	StaleAfterS    int32
	LastRunAt      pgtype.Timestamptz
	LastRunStatus  string
	LastError      pgtype.Text
	LastSuccessAt  pgtype.Timestamptz
	LastPointAt    pgtype.Timestamptz
}

func (q *Queries) SourceHealth(ctx context.Context) ([]SourceHealthRow, error) {
	rows, err := q.db.Query(ctx, sourceHealth)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SourceHealthRow{}
	for rows.Next() {
		var i SourceHealthRow
		if err := rows.Scan(
			&i.Slug,
			&i.NameFa,
			&i.NameEn,
			&i.Provider,
			&i.Active,
			&i.FetchIntervalS,
			&i.StaleAfterS,
			&i.LastRunAt,
			&i.LastRunStatus,
			&i.LastError,
			&i.LastSuccessAt,
			&i.LastPointAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertLatest = `-- name: UpsertLatest :exec
INSERT INTO market.price_latest (series_id, point_id, price_minor, observed_at, source_id, prev_close_minor, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, now())
ON CONFLICT (series_id) DO UPDATE SET
  point_id = EXCLUDED.point_id, price_minor = EXCLUDED.price_minor, observed_at = EXCLUDED.observed_at,
  source_id = EXCLUDED.source_id, prev_close_minor = EXCLUDED.prev_close_minor, updated_at = now()
`

type UpsertLatestParams struct {
	SeriesID       int32
	PointID        int64
	PriceMinor     int64
	ObservedAt     pgtype.Timestamptz
	SourceID       int16
	PrevCloseMinor pgtype.Int8
}

func (q *Queries) UpsertLatest(ctx context.Context, arg UpsertLatestParams) error {
	_, err := q.db.Exec(ctx, upsertLatest,
		arg.SeriesID,
		arg.PointID,
		arg.PriceMinor,
		arg.ObservedAt,
		arg.SourceID,
		arg.PrevCloseMinor,
	)
	return err
}
